### 📄 `iframe-messaging.js` (or inside your main JS/TS file)

```ts
// Track current content in memory
let currentContent = '';
let suppressChange = false;

// Send a message to the parent window
function sendMessage(type, payload = {}) {
  window.parent.postMessage({ type, payload }, '*');
}

// Called when the editor finishes loading
function initializeEditor() {
  // Tell JupyterLab we're ready
  sendMessage('ready');

  // Listen for messages from JupyterLab
  window.addEventListener('message', (event) => {
    const { type, payload } = event.data || {};
    switch (type) {
      case 'loadContent':
        suppressChange = true;
        currentContent = payload.content;
        loadIntoEditor(currentContent);
        suppressChange = false;
        break;

      case 'revertContent':
        suppressChange = true;
        currentContent = payload.content;
        loadIntoEditor(currentContent);
        suppressChange = false;
        break;

      case 'saveSuccess':
        // Optionally show a status or toast
        console.log('Save successful');
        break;

      default:
        console.warn('Unknown message type:', type);
    }
  });
}

// When user changes the document
function onUserEdit(newContent) {
  if (!suppressChange && newContent !== currentContent) {
    currentContent = newContent;
    sendMessage('contentChanged', { content: newContent });
  }
}

// User triggers save
function onUserSave() {
  sendMessage('requestSave');
}

// User triggers revert
function onUserRevert() {
  sendMessage('requestRevert');
}

// You should call initializeEditor() after the editor DOM is mounted
// and hook onUserEdit, onUserSave, onUserRevert into your actual UI
