## 🧩 JupyterLab Message Handling Plan

We’ll implement a `MainAreaWidget` or `DocumentWidget` that:

- Embeds an iframe
- Listens for `galyleo:*` messages from the iframe
- Sends messages to the iframe using `iframe.contentWindow.postMessage(...)`
- Connects to the `context.model` for file I/O

---

### ✅ Here's the Jupyter-side skeleton (TypeScript):

```ts
import {
  DocumentWidget
} from '@jupyterlab/docregistry';
import {
  JupyterFrontEndPlugin
} from '@jupyterlab/application';
import {
  IFrame
} from '@jupyterlab/apputils';
import {
  DocumentRegistry
} from '@jupyterlab/docregistry';

class GalyleoWidget extends DocumentWidget<IFrame> {
  constructor(context: DocumentRegistry.Context) {
    const iframe = new IFrame({
      sandbox: ['allow-scripts', 'allow-same-origin'],
      referrerPolicy: 'no-referrer'
    });

    iframe.url = '/galyleo/studio-en/index.html';

    super({ content: iframe, context });

    this._iframe = iframe.node.querySelector('iframe')!;
    this._model = context.model;
    this._initMessageListeners();

    // Autosave, dirty state, etc.
    this._model.contentChanged.connect(() => {
      this.context.save();
    });

    context.ready.then(() => {
      // Optional: react to context restoration
    });
  }

  private _initMessageListeners(): void {
    window.addEventListener('message', (event: MessageEvent) => {
      const { type, payload } = event.data || {};
      switch (type) {
        case 'galyleo:ready':
          this._postMessage('galyleo:loadContent', {
            content: this._model.toString()
          });
          break;

        case 'galyleo:contentChanged':
          if (payload.content !== this._model.toString()) {
            this._model.fromString(payload.content);
          }
          break;

        case 'galyleo:requestSave':
          this.context.save().then(() => {
            this._postMessage('galyleo:saveSuccess');
          });
          break;

        case 'galyleo:requestRevert':
          this.context.revert().then(() => {
            this._postMessage('galyleo:revertContent', {
              content: this._model.toString()
            });
          });
          break;
      }
    });
  }

  private _postMessage(type: string, payload: any = {}): void {
    this._iframe.contentWindow?.postMessage({ type, payload }, '*');
  }

  private _iframe: HTMLIFrameElement;
  private _model: DocumentRegistry.IModel;
}
```

